const ZONE = 'Africa/Abidjan';
const now = $now.setZone(ZONE);

// Telegram refuse tout message de plus de 4096 caracteres. Une boutique qui
// laisse s accumuler ses commandes depassait la mesure, Telegram repondait 400
// et — les envois etant muets — personne ne l apprenait. Les alertes sont
// desormais decoupees en autant de messages qu il en faut.
const LIMITE = 3500;

// Le canal Telegram envoie en parse_mode HTML : tout ce qui vient du client
// doit etre echappe, sinon un nom comme « Marie & Fils » ou une adresse
// contenant un chevron fait repondre 400 a Telegram et l alerte se perd.
// La coupe precede l echappement : tronquer « &amp; » en plein milieu
// produirait exactement l erreur que l on cherche a eviter.
const ech = (v, max) => String(v == null ? '' : v)
  .slice(0, max || 120)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lignes = ($('Commandes en retard').first().json.lignes) || [];

// Ou joindre chaque marchand. Sans registre, l'alerte ne pourrait partir
// que vers un chat ecrit en dur — donc toujours le meme.
const annuaire = {};
for (const m of ($('Lire le registre').first().json.marchands) || []) {
  annuaire[String(m.id || '').trim()] = m;
}

// Anti-spam : une seule alerte par commande, remis a zero chaque jour. On ne
// fait ici que LIRE le registre ; c'est `Clore les alertes` qui l'ecrit, une
// fois l'envoi confirme.
const today = now.toFormat('yyyy-MM-dd');
const sd = $getWorkflowStaticData('global');
if (sd.retardsDate !== today) { sd.retards = {}; sd.echecsSignales = {}; sd.retardsDate = today; }
if (!sd.retards) sd.retards = {};

const nouvelles = lignes.filter((r) => r && r.order_id && !sd.retards[r.order_id]);
if (!nouvelles.length) return [];

// Un retard appartient a une boutique et a une seule : le message est
// decoupe par slug, jamais melange.
const parSlug = new Map();
for (const r of nouvelles) {
  const cle = String(r.slug || '').trim();
  if (!cle) continue;
  if (!parSlug.has(cle)) parSlug.set(cle, []);
  parSlug.get(cle).push(r);
}

const fiche = (c) => `\n• <code>${ech(c.order_id, 40)}</code> — <b>${ech(c.minutes, 10)} min</b>\n`
  + `  👤 ${ech(c.client_nom || 'Inconnu', 60)} · 📞 ${ech(c.client_telephone || 'N/A', 30)}\n`
  + `  📍 ${ech(c.client_adresse || 'N/A', 120)}\n`
  + `  🛵 ${ech(c.nom_livreur || 'Non assigne', 60)} · ${ech(c.statut_livraison || c.statut || 'inconnu', 40)}\n`;

const sorties = [];
for (const [slug, cmds] of parSlug) {
  const m = annuaire[slug] || {};
  const destinataire = String(m.telegramMarchand || '').trim();

  // Sans chat Telegram renseigne, on n'a personne a prevenir : le dire dans
  // le journal vaut mieux qu'un envoi qui partirait chez quelqu'un d'autre.
  // La commande n'est PAS marquee : elle doit rester signalable le jour ou
  // le marchand renseignera son identifiant.
  if (!destinataire) {
    console.log(`Retards ${slug} : ${cmds.length} commande(s), aucun Telegram gerant renseigne.`);
    continue;
  }

  const nom = ech(cmds[0].boutique_nom || slug, 80);

  const tranches = [];
  let courante = [];
  let taille = 0;
  for (const c of cmds) {
    const bloc = fiche(c);
    if (courante.length && taille + bloc.length > LIMITE) {
      tranches.push(courante);
      courante = [];
      taille = 0;
    }
    courante.push({ c, bloc });
    taille += bloc.length;
  }
  if (courante.length) tranches.push(courante);

  tranches.forEach((tranche, i) => {
    const suite = tranches.length > 1 ? ` (${i + 1}/${tranches.length})` : '';
    let message = `⚠️ <b>ALERTE RETARD</b>${suite}\n🕐 Verification : ${now.toFormat('HH:mm')}\n`;
    message += `\n🏪 <b>${nom}</b> — ${cmds.length} commande(s)\n`;
    for (const t of tranche) message += t.bloc;
    message += `\n📌 <b>Action</b> : contacter les livreurs concernes.`;

    // `order_ids` voyage avec le message : `Clore les alertes` ne peut marquer
    // que ce qui est effectivement parti.
    sorties.push({ json: {
      slug,
      destinataire,
      message,
      nombre: tranche.length,
      order_ids: tranche.map((t) => String(t.c.order_id)),
    } });
  });
}

return sorties;

// L ecriture du registre anti-doublon a lieu ICI, apres l envoi.
//
// Elle etait faite a la composition du message : une alerte perdue en route
// etait pourtant classee « signalee », et le retard ne remontait plus de la
// journee entiere.
const ZONE = 'Africa/Abidjan';
const today = $now.setZone(ZONE).toFormat('yyyy-MM-dd');

const sd = $getWorkflowStaticData('global');
if (sd.retardsDate !== today) { sd.retards = {}; sd.retardsDate = today; }
if (!sd.retards) sd.retards = {};

const demandes = $('Identifier retards').all();
const verdicts = $input.all();

// `Envoyer alerte gerant` tolere son propre echec : c est la seule facon que ce
// noeud-ci s execute quand l envoi a echoue, et donc que la commande NE SOIT
// PAS marquee. Le signalement a l exploitant, lui, est fait par
// `Envoyer reponse client`, qui leve de son cote — le refaire ici donnerait
// deux alertes pour un seul incident.
//
// Et ce noeud NE DOIT PAS lever non plus : n8n n enregistre la memoire statique
// qu au terme d une execution reussie. Lever ici jetterait le registre qu on
// vient d ecrire, et chaque passage realerterait sur les memes commandes.
const verdictDe = new Map();
verdicts.forEach((v, i) => {
  const idx = v.pairedItem && typeof v.pairedItem.item === 'number' ? v.pairedItem.item : i;
  if (!verdictDe.has(idx)) verdictDe.set(idx, v.json || {});
});

const echecs = [];
demandes.forEach((demande, i) => {
  const d = demande.json || {};
  const j = verdictDe.get(i) || {};

  if (j.ok === true) {
    for (const id of (d.order_ids || [])) sd.retards[id] = true;
    return;
  }

  // Pas de marquage : la commande reste signalable au passage suivant.
  echecs.push({
    boutique: String(d.slug || ''),
    chat: String(d.destinataire || ''),
    commandes: (d.order_ids || []),
    cause: String(j.erreur || (j.error && j.error.message) || 'envoi interrompu').slice(0, 200),
  });
});

return [{ json: {
  alertes: demandes.length,
  delivrees: demandes.length - echecs.length,
  suivies: Object.keys(sd.retards).length,
  echecs,
} }];
